package dynamicprogramming;
public class WeightedEditDistance { public static int distance(String a,String b,int insert,int delete,int replace){int[][] d=new int[a.length()+1][b.length()+1];for(int i=1;i<=a.length();i++)d[i][0]=i*delete;for(int j=1;j<=b.length();j++)d[0][j]=j*insert;for(int i=1;i<=a.length();i++)for(int j=1;j<=b.length();j++){int c=Character.toLowerCase(a.charAt(i-1))==Character.toLowerCase(b.charAt(j-1))?0:replace;d[i][j]=Math.min(Math.min(d[i-1][j]+delete,d[i][j-1]+insert),d[i-1][j-1]+c);}return d[a.length()][b.length()];} }
